41	/**
42	 * Global Exception handler for REST controllers.
43	 * <p>
44	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
45	 *
46	 * @author Vitaliy Fedoriv
47	 * @author Alexander Dudkin
48	 */
49	@ControllerAdvice
50	public class ExceptionControllerAdvice {
51	
52	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
53	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
54	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
55	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
56	
57	    /**
58	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
59	     * class.
60	     *
61	     * @param e     Object referring to the thrown exception.
62	     * @param status HTTP response status.
63	     * @param url URL request.
64	     */
65	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
66	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
67	        problemDetail.setType(URI.create(url.toString()));
68	        problemDetail.setTitle(e.getClass().getSimpleName());
69	        problemDetail.setDetail(detail);
70	        problemDetail.setProperty("timestamp", Instant.now());
71	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
72	        return problemDetail;
73	    }
74	
75	    /**
76	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
77	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
78	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
79	     * would catch it and report an authorization failure as a 500.
80	     *
81	     * @param e The {@link AccessDeniedException} to propagate
82	     * @throws AccessDeniedException always
83	     */
84	    @ExceptionHandler(AccessDeniedException.class)
85	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
86	        throw e;
87	    }
88	
89	    /**
90	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
91	     *
92	     * @param e The {@link Exception} to be handled
93	     * @param request {@link HttpServletRequest} object referring to the current request.
94	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
95	     */
96	    @ExceptionHandler(Exception.class)
97	    @ResponseBody
98	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
99	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
100	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
101	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
102	        return ResponseEntity.status(status).body(detail);
103	    }
104	
105	    /**
106	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
107	     * method returns a 404 Not Found status if an entity does not exist.
108	     *
109	     * @param e The {@link DataIntegrityViolationException} to be handled
110	     * @param request {@link HttpServletRequest} object referring to the current request.
111	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
112	     */
113	    @ExceptionHandler(DataIntegrityViolationException.class)
114	    @ResponseBody
115	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
116	        logger.warn("Data integrity violation at {} {}: {}",
117	            request.getMethod(),
118	            request.getRequestURI(),
119	            e.getMessage());
120	        logger.debug("Data integrity violation stacktrace", e);
121	        HttpStatus status = HttpStatus.NOT_FOUND;
122	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
123	        return ResponseEntity.status(status).body(detail);
124	    }
125	
126	    /**
127	     * Handles {@link InvalidOwnerFieldsException} thrown when an owner is created or updated with
128	     * required fields that are missing or blank (for example, whitespace-only values that Bean
129	     * Validation does not reject). Returns a 400 Bad Request whose {@code errors} array lists the
130	     * name of each offending field.
131	     *
132	     * @param e The {@link InvalidOwnerFieldsException} to be handled
133	     * @param request {@link HttpServletRequest} object referring to the current request.
134	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
135	     */
136	    @ExceptionHandler(InvalidOwnerFieldsException.class)
137	    @ResponseBody
138	    public ResponseEntity<ProblemDetail> handleInvalidOwnerFieldsException(InvalidOwnerFieldsException e, HttpServletRequest request) {
139	        logger.debug("Invalid owner fields at {} {}: {}",
140	            request.getMethod(),
141	            request.getRequestURI(),
142	            e.getFields());
143	        HttpStatus status = HttpStatus.BAD_REQUEST;
144	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
145	        detail.setProperty("errors", e.getFields());
146	        return ResponseEntity.status(status).body(detail);
147	    }
148	
149	    /**
150	     * Handles {@link DuplicateOwnerIdentityException} thrown when an owner is created whose derived
151	     * {@code identityKey} - the SHA-256 hex digest of {@code normalizedTelephone + '|' + lowerEmail +
152	     * '|' + soundex(lastName)} - already belongs to another owner. Returns a 409 Conflict whose
153	     * {@code errors} array names {@code identityKey}.
154	     *
155	     * @param e The {@link DuplicateOwnerIdentityException} to be handled
156	     * @param request {@link HttpServletRequest} object referring to the current request.
157	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
158	     */
159	    @ExceptionHandler(DuplicateOwnerIdentityException.class)
160	    @ResponseBody
161	    public ResponseEntity<ProblemDetail> handleDuplicateOwnerIdentityException(DuplicateOwnerIdentityException e, HttpServletRequest request) {
162	        logger.debug("Duplicate owner identity at {} {}: {}",
163	            request.getMethod(),
164	            request.getRequestURI(),
165	            e.getIdentityKey());
166	        HttpStatus status = HttpStatus.CONFLICT;
167	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
168	        detail.setProperty("errors", List.of("identityKey"));
169	        return ResponseEntity.status(status).body(detail);
170	    }
171	
172	    /**
173	     * Handles {@link OwnerCityAtCapacityException} thrown when an owner is created whose city
174	     * already contains the maximum number of owners (50), compared case-insensitively. Returns a
175	     * 409 Conflict whose {@code errors} array names {@code city}.
176	     *
177	     * @param e The {@link OwnerCityAtCapacityException} to be handled
178	     * @param request {@link HttpServletRequest} object referring to the current request.
179	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
180	     */
181	    @ExceptionHandler(OwnerCityAtCapacityException.class)
182	    @ResponseBody
183	    public ResponseEntity<ProblemDetail> handleOwnerCityAtCapacityException(OwnerCityAtCapacityException e, HttpServletRequest request) {
184	        logger.debug("Owner city at capacity at {} {}: {}",
185	            request.getMethod(),
186	            request.getRequestURI(),
187	            e.getCity());
188	        HttpStatus status = HttpStatus.CONFLICT;
189	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
190	        detail.setProperty("errors", List.of("city"));
191	        return ResponseEntity.status(status).body(detail);
192	    }
193	
194	    /**
195	     * Handles {@link DailyOwnerLimitReachedException} thrown when an owner is created after the
196	     * maximum number of owners for the day (100), counted by {@code registrationDate}, has already
197	     * been reached. Returns a 429 Too Many Requests.
198	     *
199	     * @param e The {@link DailyOwnerLimitReachedException} to be handled
200	     * @param request {@link HttpServletRequest} object referring to the current request.
201	     * @return A {@link ResponseEntity} containing the error information and a 429 Too Many Requests status.
202	     */
203	    @ExceptionHandler(DailyOwnerLimitReachedException.class)
204	    @ResponseBody
205	    public ResponseEntity<ProblemDetail> handleDailyOwnerLimitReachedException(DailyOwnerLimitReachedException e, HttpServletRequest request) {
206	        logger.debug("Daily owner limit reached at {} {}: {}",
207	            request.getMethod(),
208	            request.getRequestURI(),
209	            e.getDate());
210	        HttpStatus status = HttpStatus.TOO_MANY_REQUESTS;
211	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
212	        return ResponseEntity.status(status).body(detail);
213	    }
214	
215	    /**
216	     * Handles exception thrown by Bean Validation on controller methods parameters
217	     *
218	     * @param e The {@link MethodArgumentNotValidException} to be handled
219	     * @param request {@link HttpServletRequest} object referring to the current request.
220	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
221	     */
222	    @ExceptionHandler(MethodArgumentNotValidException.class)
223	    @ResponseBody
224	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
225	        HttpStatus status = HttpStatus.BAD_REQUEST;
226	        BindingErrorsResponse errors = new BindingErrorsResponse();
227	        BindingResult bindingResult = e.getBindingResult();
228	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
229	        if (bindingResult.hasErrors()) {
230	            errors.addAllErrors(bindingResult);
231	            List<String> invalidFields = bindingResult.getFieldErrors().stream()
232	                .map(FieldError::getField)
233	                .distinct()
234	                .toList();
235	            detail.setProperty("errors", invalidFields);
236	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
237	                .map(fieldError -> {
238	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
239	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
240	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
241	                        fieldError.getField(),
242	                        defaultMessage,
243	                        rejectedValue);
244	                    return new ValidationMessageDto(message)
245	                        .putAdditionalProperty("field", fieldError.getField())
246	                        .putAdditionalProperty("rejectedValue", rejectedValue)
247	                        .putAdditionalProperty("defaultMessage", defaultMessage);
248	                })
249	                .toList();
250	            logger.debug("Validation error at {} {}: {}",
251	                request.getMethod(),
252	                request.getRequestURI(),
253	                bindingResult.getFieldErrors());
254	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
255	            return ResponseEntity.status(status).body(detail);
256	        }
257	        return ResponseEntity.status(status).body(detail);
258	    }
259	
260	}
